//! T03 cleaned-projection wire battery: envelope order, contract version,
//! inline full-text transfer, fail-closed truncation and honest completion.
//!
//! Every per-fixture expectation in this file is a **handwritten oracle** taken
//! from the frozen `source_package` substrate and the pinned reader projection
//! (never generated by the module under test). The pinned `mixed-wordml.xml`
//! fixture and the nine positive reader fixtures are driven through
//! `source_package::capture` → `reader_projection::build_projection` →
//! `cleaned_wire::render_cleaned_projection` →
//! `cleaned_wire::inspect_cleaned_wire`.
//!
//! Non-claims: this battery is `[bounded]` to the self-authored non-legal
//! synthetic fixtures under `tests/fixtures/reader/`; it is not corpus coverage,
//! not source authenticity and not a legal-completeness claim. Counts and seals
//! are integrity, not coverage. R1000 stays active. Raw decoded legal text is
//! never logged.

use std::collections::HashMap;

use ln_decode::cleaned_wire::{
    inspect_cleaned_wire, render_cleaned_projection, IncompleteReason, WireCompletion, WireError,
    WireErrorKind, WireLimits, KIND_FOOTER, KIND_MANIFEST, KIND_POLICIES, KIND_SEGMENT,
};
use ln_decode::reader_projection::{build_projection, ReaderProjection};
use ln_decode::reader_verifier::verify_projection;
use ln_decode::source_package::{capture, Limits, Package, Record};

