fn project(fixture: &Fixture) -> (Package, ReaderProjection) {
    let package = capture(fixture.xml.as_bytes(), &Limits::default())
        .unwrap_or_else(|error| panic!("{} must capture: {error:?}", fixture.file));
    assert_eq!(
        package.manifest().source.sha256,
        fixture.sha256,
        "{}: content changed; re-pin the sha256 oracle",
        fixture.file
    );
    let projection = build_projection(package.records())
        .unwrap_or_else(|error| panic!("{} must project: {error:?}", fixture.file));
    (package, projection)
}

fn render(
    package: &Package,
    projection: &ReaderProjection,
    completion: &WireCompletion,
) -> Result<String, WireError> {
    render_cleaned_projection(package, projection, completion, &WireLimits::default())
}

fn expect_error(document: &str) -> WireError {
    inspect_cleaned_wire(document).expect_err("a structurally broken envelope must be refused")
}

// ------------------------------------------- independent JSON field reader #
//
// A hand-written top-level object reader, independent of the module under test.
// The writer emits one compact ascending-key object per line.

fn skip_value(line: &str, start: usize) -> usize {
    let bytes = line.as_bytes();
    let mut index = start;
    match bytes.get(index) {
        Some(b'"') => {
            index += 1;
            while index < bytes.len() {
                match bytes[index] {
                    b'\\' => index += 2,
                    b'"' => {
                        index += 1;
                        break;
                    }
                    _ => index += 1,
                }
            }
        }
        Some(b'{') | Some(b'[') => {
            let mut depth = 0usize;
            while index < bytes.len() {
                match bytes[index] {
                    b'"' => {
                        index += 1;
                        while index < bytes.len() {
                            match bytes[index] {
                                b'\\' => index += 2,
                                b'"' => {
                                    index += 1;
                                    break;
                                }
                                _ => index += 1,
                            }
                        }
                    }
                    b'{' | b'[' => {
                        depth += 1;
                        index += 1;
                    }
                    b'}' | b']' => {
                        depth = depth.saturating_sub(1);
                        index += 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => index += 1,
                }
            }
        }
        _ => {
            while index < bytes.len() {
                let byte = bytes[index];
                if byte == b',' || byte == b'}' || byte == b']' || byte.is_ascii_whitespace() {
                    break;
                }
                index += 1;
            }
        }
    }
    index
}

fn parse_fields(line: &str) -> Vec<(&str, &str)> {
    let bytes = line.as_bytes();
    assert!(
        bytes.len() >= 2 && bytes[0] == b'{' && bytes[bytes.len() - 1] == b'}',
        "every wire line must be a compact JSON object"
    );
    let end = bytes.len() - 1;
    let mut entries: Vec<(&str, &str)> = Vec::new();
    let mut index = 1usize;
    while index < end {
        while index < end && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        if index >= end {
            break;
        }
        assert_eq!(bytes[index], b'"', "object key must be a JSON string");
        let key_start = index + 1;
        index += 1;
        let mut key_end = None;
        while index < bytes.len() {
            match bytes[index] {
                b'\\' => index += 2,
                b'"' => {
                    key_end = Some(index);
                    index += 1;
                    break;
                }
                _ => index += 1,
            }
        }
        let key = &line[key_start..key_end.expect("unterminated object key")];
        while index < end && bytes[index] != b':' {
            index += 1;
        }
        assert_eq!(bytes[index], b':');
        index += 1;
        while index < end && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        let value_start = index;
        index = skip_value(line, index);
        entries.push((key, &line[value_start..index]));
        while index < end && (bytes[index] == b',' || bytes[index].is_ascii_whitespace()) {
            index += 1;
        }
    }
    entries
}

fn unescape(raw: &str) -> Option<String> {
    let inner = raw.strip_prefix('"')?.strip_suffix('"')?;
    let mut out = String::with_capacity(inner.len());
    let mut chars = inner.chars();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            out.push(ch);
            continue;
        }
        match chars.next()? {
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            'n' => out.push('\n'),
            'r' => out.push('\r'),
            't' => out.push('\t'),
            'b' => out.push('\u{8}'),
            'f' => out.push('\u{c}'),
            'u' => {
                let mut code = 0u32;
                for _ in 0..4 {
                    code = code * 16 + chars.next()?.to_digit(16)?;
                }
                out.push(char::from_u32(code)?);
            }
            _ => return None,
        }
    }
    Some(out)
}

fn str_field(entries: &[(&str, &str)], key: &str) -> Option<String> {
    entries
        .iter()
        .find(|(name, _)| *name == key)
        .and_then(|(_, value)| unescape(value))
}

fn is_null(entries: &[(&str, &str)], key: &str) -> bool {
    entries
        .iter()
        .find(|(name, _)| *name == key)
        .map(|(_, value)| value.trim() == "null")
        .unwrap_or(false)
}

// -------------------------------------------------------------- envelope #

#[test]
fn every_fixture_renders_a_compact_ordered_envelope() {
    for fixture in ALL {
        let (package, projection) = project(fixture);
        let completion = WireCompletion::Complete;
        let first = render(&package, &projection, &completion).unwrap_or_else(|error| {
            panic!("{}: complete render must succeed: {error}", fixture.file)
        });
        let second = render(&package, &projection, &completion)
            .unwrap_or_else(|error| panic!("{}: second render: {error}", fixture.file));
        assert_eq!(
            first, second,
            "{}: repeated renders must be byte-identical",
            fixture.file
        );

        assert!(
            first.ends_with('\n'),
            "{}: exactly one trailing LF",
            fixture.file
        );
        assert!(
            !first.contains('\r'),
            "{}: no carriage return",
            fixture.file
        );

        let lines: Vec<&str> = first.split_terminator('\n').collect();
        assert!(
            lines.len() >= 3,
            "{}: manifest, policies and footer at minimum",
            fixture.file
        );
        for line in &lines {
            assert!(
                line.starts_with('{') && line.ends_with('}'),
                "{}: every line is one compact JSON object",
                fixture.file
            );
        }

        let first_fields = parse_fields(lines[0]);
        let second_fields = parse_fields(lines[1]);
        let last_fields = parse_fields(lines.last().expect("non-empty document"));
        assert_eq!(
            str_field(&first_fields, "kind").as_deref(),
            Some(KIND_MANIFEST),
            "{}: line 0 kind",
            fixture.file
        );
        assert_eq!(
            str_field(&second_fields, "kind").as_deref(),
            Some(KIND_POLICIES),
            "{}: line 1 kind",
            fixture.file
        );
        assert_eq!(
            str_field(&last_fields, "kind").as_deref(),
            Some(KIND_FOOTER),
            "{}: last line kind",
            fixture.file
        );

        let summary = inspect_cleaned_wire(&first).unwrap_or_else(|error| {
            panic!(
                "{}: inspect must accept the envelope: {error}",
                fixture.file
            )
        });
        assert_eq!(
            summary.contract_version, 1,
            "{}: contract version",
            fixture.file
        );
        assert_eq!(
            summary.completion, "complete",
            "{}: completion",
            fixture.file
        );
        assert!(
            summary.incomplete_reasons.is_empty(),
            "{}: complete carries no reasons",
            fixture.file
        );
        assert_eq!(
            summary.records,
            summary.views + summary.segments + summary.references,
            "{}: record total is recomputed from the record lines",
            fixture.file
        );
    }
}

#[test]
fn full_text_is_carried_inline_exactly_once() {
    for fixture in ALL {
        let (package, projection) = project(fixture);
        assert!(
            verify_projection(&projection, package.records()).is_ok(),
            "{}: untampered projection must verify",
            fixture.file
        );

        let document = render(&package, &projection, &WireCompletion::Complete)
            .unwrap_or_else(|error| panic!("{}: render: {error}", fixture.file));
        let lines: Vec<&str> = document.split_terminator('\n').collect();

        let substrate: HashMap<&str, &str> = package
            .records()
            .iter()
            .filter_map(|record| match record {
                Record::Text(text) => Some((text.id.as_str(), text.value.as_str())),
                Record::Element(_) => None,
            })
            .collect();

        let mut seen: HashMap<String, u64> = HashMap::new();
        let mut source_text_bytes: u64 = 0;
        for line in &lines {
            let fields = parse_fields(line);
            if str_field(&fields, "kind").as_deref() != Some(KIND_SEGMENT) {
                continue;
            }
            let origin = str_field(&fields, "origin").expect("segment must carry origin");
            let segment_kind = str_field(&fields, "segment_kind").expect("segment must carry kind");
            let text =
                str_field(&fields, "text").expect("segment.text must be present on every segment");
            if origin == "source_fragment" {
                assert_eq!(
                    segment_kind, "text",
                    "{}: source segment kind",
                    fixture.file
                );
                let fragment = str_field(&fields, "fragment_ref")
                    .expect("source segment must carry fragment_ref");
                assert!(
                    !is_null(&fields, "span"),
                    "{}: source segment {fragment} must carry a span",
                    fixture.file
                );
                assert_eq!(
                    substrate.get(fragment.as_str()).copied(),
                    Some(text.as_str()),
                    "{}: inline text must equal the substrate value for {fragment}",
                    fixture.file
                );
                *seen.entry(fragment).or_insert(0) += 1;
                source_text_bytes += text.len() as u64;
            } else {
                assert!(
                    origin.starts_with("derived:"),
                    "{}: unexpected origin {origin}",
                    fixture.file
                );
                assert_eq!(
                    segment_kind, "derived",
                    "{}: derived segment kind",
                    fixture.file
                );
                assert!(
                    is_null(&fields, "fragment_ref"),
                    "{}: derived segment must not carry a fragment_ref",
                    fixture.file
                );
                assert!(
                    is_null(&fields, "span"),
                    "{}: derived segment must not carry a span",
                    fixture.file
                );
            }
        }

        let mut expected: Vec<&str> = substrate.keys().copied().collect();
        let mut actual: Vec<&str> = seen.keys().map(String::as_str).collect();
        expected.sort_unstable();
        actual.sort_unstable();
        assert_eq!(
            actual, expected,
            "{}: every substrate text fragment must be attributed exactly once",
            fixture.file
        );
        assert!(
            seen.values().all(|count| *count == 1),
            "{}: no fragment may be attributed twice",
            fixture.file
        );
        assert_eq!(
            source_text_bytes,
            package.footer().counts.text_bytes,
            "{}: summed source text_bytes equals the substrate footer text_bytes",
            fixture.file
        );

        let summary = inspect_cleaned_wire(&document).expect("rendered envelope must inspect");
        assert_eq!(
            summary.source_segments as usize,
            seen.len(),
            "{}: footer source_segments matches the attributed fragments",
            fixture.file
        );
    }
}

// ------------------------------------------------------- fail-closed cuts #

#[test]
fn structural_truncation_is_fail_closed() {
    let (package, projection) = project(&MIXED);
    let document = render(&package, &projection, &WireCompletion::Complete).expect("render");
    let lines: Vec<String> = document
        .split_terminator('\n')
        .map(str::to_string)
        .collect();

    // 1. delete the footer line entirely.
    let without_footer = format!("{}\n", lines[..lines.len() - 1].join("\n"));
    assert_eq!(
        expect_error(&without_footer).kind(),
        WireErrorKind::MissingFooter
    );

    // 2. swap the manifest and policies lines.
    let mut swapped = lines.clone();
    swapped.swap(0, 1);
    assert_eq!(
        expect_error(&format!("{}\n", swapped.join("\n"))).kind(),
        WireErrorKind::MisorderedPolicies
    );

    // 3. insert an empty interior line.
    let mut with_empty = lines.clone();
    with_empty.insert(1, String::new());
    assert_eq!(
        expect_error(&format!("{}\n", with_empty.join("\n"))).kind(),
        WireErrorKind::EmptyLine
    );

    // 4. strip the trailing LF.
    let stripped = document.strip_suffix('\n').expect("document ends with LF");
    assert_eq!(
        expect_error(stripped).kind(),
        WireErrorKind::MissingTrailingLf
    );

    // 5. an unknown line discriminator.
    let unknown = document.replacen(
        "\"kind\":\"cleaned_projection_segment\"",
        "\"kind\":\"bogus_kind\"",
        1,
    );
    assert_eq!(expect_error(&unknown).kind(), WireErrorKind::UnknownKind);

    // 6. a carriage return anywhere in the document.
    let mut with_cr = lines.clone();
    with_cr[2].push('\r');
    assert_eq!(
        expect_error(&format!("{}\n", with_cr.join("\n"))).kind(),
        WireErrorKind::CarriageReturn
    );

    // 7. a manifest schema that is not the pinned tag.
    let bad_schema = document.replacen(
        "law-nexus/cleaned-projection-manifest/v1",
        "law-nexus/cleaned-projection-manifest/v9",
        1,
    );
    assert_eq!(
        expect_error(&bad_schema).kind(),
        WireErrorKind::SchemaMismatch
    );

    // 8. a contract version other than 1.
    let bad_version = document.replacen("\"version\":1", "\"version\":2", 1);
    assert_eq!(
        expect_error(&bad_version).kind(),
        WireErrorKind::VersionMismatch
    );

    // 9. a seal that is not 64 lowercase hex.
    let footer_fields = parse_fields(lines.last().expect("footer line"));
    let seal = str_field(&footer_fields, "records_seal_hash").expect("footer records_seal_hash");
    let bad_hash = document.replacen(&seal, "not-a-valid-seal", 1);
    assert_eq!(
        expect_error(&bad_hash).kind(),
        WireErrorKind::HashShapeInvalid
    );

    // 10. a record line after the footer.
    let mut moved = lines.clone();
    let footer = moved.pop().expect("footer");
    let last_record = moved.pop().expect("record");
    moved.push(footer);
    moved.push(last_record);
    assert_eq!(
        expect_error(&format!("{}\n", moved.join("\n"))).kind(),
        WireErrorKind::TrailingRecordAfterFooter
    );
}

// ------------------------------------------------------------- completion #

#[test]
fn completion_marker_is_honest_and_closed() {
    let (package, projection) = project(&MIXED);

    let caller_scope = WireCompletion::Incomplete {
        basis: IncompleteReason::CallerScope,
        reasons: vec![IncompleteReason::CallerScope],
    };
    let document =
        render(&package, &projection, &caller_scope).expect("honest partial export renders");
    let summary = inspect_cleaned_wire(&document).expect("honest partial export inspects");
    assert_eq!(summary.completion, "incomplete");
    assert_eq!(summary.completion_basis, "caller_scope");
    assert_eq!(summary.incomplete_reasons, vec!["caller_scope".to_string()]);

    let hold_and_text_only = WireCompletion::Incomplete {
        basis: IncompleteReason::Hold,
        reasons: vec![IncompleteReason::Hold, IncompleteReason::TextOnly],
    };
    let multi = render(&package, &projection, &hold_and_text_only).expect("multi-reason render");
    let multi_summary = inspect_cleaned_wire(&multi).expect("multi-reason inspect");
    assert_eq!(multi_summary.completion, "incomplete");
    assert_eq!(multi_summary.completion_basis, "hold");
    assert_eq!(
        multi_summary.incomplete_reasons,
        vec!["hold".to_string(), "text_only".to_string()]
    );

    // `complete` with a dropped source segment is refused by the writer.
    let mut lost = projection.clone();
    let source_index = lost
        .segments
        .iter()
        .position(|segment| segment.fragment_ref.is_some())
        .expect("fixture must carry a source segment");
    lost.segments.remove(source_index);
    let error = render(&package, &lost, &WireCompletion::Complete).expect_err("loss must refuse");
    assert_eq!(error.kind(), WireErrorKind::TextLoss);

    // `complete` with a duplicated source segment is refused too.
    let mut duplicated = projection.clone();
    let duplicated_segment = duplicated
        .segments
        .iter()
        .find(|segment| segment.fragment_ref.is_some())
        .expect("fixture must carry a source segment")
        .clone();
    duplicated.segments.push(duplicated_segment);
    let error = render(&package, &duplicated, &WireCompletion::Complete)
        .expect_err("duplicate must refuse");
    assert_eq!(error.kind(), WireErrorKind::TextLoss);

    // `incomplete` with no reason is refused.
    let no_reason = WireCompletion::Incomplete {
        basis: IncompleteReason::Hold,
        reasons: Vec::new(),
    };
    let error = render(&package, &projection, &no_reason).expect_err("no reason must refuse");
    assert_eq!(error.kind(), WireErrorKind::CompletionMarkerInvalid);

    // `incomplete` whose basis is absent from the reason set is refused.
    let basis_absent = WireCompletion::Incomplete {
        basis: IncompleteReason::Hold,
        reasons: vec![IncompleteReason::CallerScope],
    };
    let error = render(&package, &projection, &basis_absent).expect_err("basis absent must refuse");
    assert_eq!(error.kind(), WireErrorKind::CompletionMarkerInvalid);

    // The inspector refuses a tampered footer that drops its reasons.
    let collapsed = document.replacen(
        "\"incomplete_reasons\":[\"caller_scope\"]",
        "\"incomplete_reasons\":[]",
        1,
    );
    assert_eq!(
        inspect_cleaned_wire(&collapsed)
            .expect_err("tampered completion must be refused")
            .kind(),
        WireErrorKind::CompletionMarkerInvalid
    );
}

// -------------------------------------------------------------- serde-free #

/// Removes `//` and `/* */` comments (string/char aware) so the check looks at
/// code only, not prose. The module doc comment contains the word "serde-free".
fn strip_rust_comments(source: &str) -> String {
    let bytes = source.as_bytes();
    let mut out = String::with_capacity(source.len());
    let mut index = 0usize;
    let mut in_string = false;
    let mut in_char = false;
    while index < bytes.len() {
        let byte = bytes[index];
        if in_string {
            out.push(byte as char);
            if byte == b'\\' && index + 1 < bytes.len() {
                out.push(bytes[index + 1] as char);
                index += 2;
                continue;
            }
            if byte == b'"' {
                in_string = false;
            }
            index += 1;
            continue;
        }
        if in_char {
            out.push(byte as char);
            if byte == b'\\' && index + 1 < bytes.len() {
                out.push(bytes[index + 1] as char);
                index += 2;
                continue;
            }
            if byte == b'\'' {
                in_char = false;
            }
            index += 1;
            continue;
        }
        if byte == b'/' && index + 1 < bytes.len() && bytes[index + 1] == b'/' {
            while index < bytes.len() && bytes[index] != b'\n' {
                index += 1;
            }
            continue;
        }
        if byte == b'/' && index + 1 < bytes.len() && bytes[index + 1] == b'*' {
            index += 2;
            while index + 1 < bytes.len() && !(bytes[index] == b'*' && bytes[index + 1] == b'/') {
                index += 1;
            }
            index = (index + 2).min(bytes.len());
            continue;
        }
        if byte == b'"' {
            in_string = true;
        } else if byte == b'\'' {
            // Only a `'x'` / `'\...'` char literal opens char state; a lifetime
            // apostrophe (e.g. `<'a>` or `'_`) must not swallow following code.
            let looks_like_char = match bytes.get(index + 1) {
                Some(b'\\') => true,
                Some(_) => bytes.get(index + 2) == Some(&b'\''),
                None => false,
            };
            if looks_like_char {
                in_char = true;
            }
        }
        out.push(byte as char);
        index += 1;
    }
    out
}

#[test]
fn cleaned_wire_source_is_serde_free() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/src/cleaned_wire.rs");
    let source = std::fs::read_to_string(path).expect("cleaned_wire source must be readable");
    let code = strip_rust_comments(&source);
    assert!(
        !code.contains("serde"),
        "cleaned_wire must not depend on serde (D328/D602/D633)"
    );
    assert!(
        !code.contains("extern crate"),
        "cleaned_wire must not pull an external JSON crate"
    );
}
